@Test
public void testMDC() throws Exception {
    MDC.put("Key1", "John");
    MDC.put("Key2", "Smith");
    Logger logger = Logger.getLogger("org.apache.test.logging");
    logger.debug("This is a test");
    ListAppender listApp = (ListAppender) CTX.getAppender("List");
    assertNotNull(listApp);
