public void testSmallestBufferSize() throws Exception {
    final Layout<String> layout = PatternLayout.newBuilder().withPattern(PatternLayout.SIMPLE_CONVERSION_PATTERN).build();
    final String bufferSizeStr = "1";
    final FileAppender appender = FileAppender.createAppender(FILENAME, "true", "false", "test", "false", "false", "false", bufferSizeStr, layout, null, "false", null, null);
    appender.start();
    final File file = new File(FILENAME);
    assertTrue("Appender did not start", appender.isStarted());
    long curLen = file.length();
    long prevLen = curLen;
    assertTrue("File length: " + curLen, curLen == 0);
    for (int i = 0; i < 100; ++i) {
        final LogEvent event = //
        Log4jLogEvent.newBuilder().setLoggerName("TestLogger").setLoggerFqcn(FileAppenderTest.class.getName()).setLevel(//
        Level.INFO).setMessage(new SimpleMessage("Test")).setThreadName(//
        this.getClass().getSimpleName()).setTimeMillis(System.currentTimeMillis()).build();
        try {
            appender.append(event);
            curLen = file.length();
            assertTrue("File length: " + curLen, curLen > prevLen);
            // Give up control long enough for another thread/process to occasionally do
            Thread.sleep(25);
            // something.
        } catch (final Exception ex) {
            throw ex;
        }
        prevLen = curLen;
    }
    appender.stop();
    assertFalse("Appender did not stop", appender.isStarted());
}

