    DefaultRolloverStrategy.FileExtensions ext = DefaultRolloverStrategy.FileExtensions.lookup(fileExtension);
    if (ext == null || DefaultRolloverStrategy.FileExtensions.ZIP == ext || DefaultRolloverStrategy.FileExtensions.PACK200 == ext) {
        // commons compress cannot deflate zip? TODO test decompressing these formats
        return;
