    assertTrue(buffer.isEmpty());
    buffer.add(1);
    assertFalse(buffer.isEmpty());
    Integer[] items = buffer.removeAll();
    assertTrue("Incorrect number of items", items.length == 1);
    assertTrue(buffer.isEmpty());
    buffer.add(1);
    buffer.add(2);
    buffer.add(3);
