        }
    } finally {
        closeQuietly(executor);
    }
}

@Test
public void testReconnect() throws Exception {
    final List<String> list = new ArrayList<>();
    TestSocketServer server = new TestSocketServer(list);
    server.start();
    Thread.sleep(300);
    //System.err.println("Initializing logger");
    final Logger logger = context.getLogger();
    String message = "Log #1";
    logger.error(message);
    final String expectedHeader = "Header";
    String msg = null;
    String header = null;
    for (int i = 0; i < 5; ++i) {
        Thread.sleep(100);
        if (list.size() > 1) {
            header = list.get(0);
            msg = list.get(1);
            break;
        }
    }
    assertNotNull("No header", header);
    assertEquals(expectedHeader, header);
    assertNotNull("No message", msg);
    assertEquals(message, msg);
    logger.error(SHUTDOWN);
    server.join();
    list.clear();
    message = "Log #2";
    boolean exceptionCaught = false;
    for (int i = 0; i < 100; ++i) {
        try {
            logger.error(message);
        } catch (final AppenderLoggingException e) {
            exceptionCaught = true;
            break;
            // System.err.println("Caught expected exception");
        }
    }
    assertTrue("No Exception thrown", exceptionCaught);
    message = "Log #3";
    server = new TestSocketServer(list);
    server.start();
    Thread.sleep(300);
    msg = null;
    header = null;
    logger.error(message);
    for (int i = 0; i < 5; ++i) {
        Thread.sleep(100);
        if (list.size() > 1) {
            header = list.get(0);
            msg = list.get(1);
            break;
        }
    }
    assertNotNull("No header", header);
    assertEquals(expectedHeader, header);
    assertNotNull("No message", msg);
    assertEquals(message, msg);
    logger.error(SHUTDOWN);
    server.join();
}

