@Test
public void testTimeBaseUuid() {
    final UUID uuid = UuidUtil.getTimeBasedUuid();
    //final UUID uuid2 = UuidUtil.getTimeBasedUUID(); // unused
    final long current = (System.currentTimeMillis() * 10000) + NUM_100NS_INTERVALS_SINCE_UUID_EPOCH;
    final long time = uuid.timestamp();
    assertTrue("Incorrect time", current + 10000 - time > 0);
    final UUID[] uuids = new UUID[COUNT];
    final long start = System.nanoTime();
    for (int i = 0; i < COUNT; ++i) {
        uuids[i] = UuidUtil.getTimeBasedUuid();
    }
    final long elapsed = System.nanoTime() - start;
    System.out.println("Elapsed for " + COUNT + " UUIDS = " + elapsed + " Average = " + elapsed / COUNT + " ns");
    int errors = 0;
    for (int i = 0; i < COUNT; ++i) {
        for (int j = i + 1; j < COUNT; ++j) {
            if (uuids[i].equals(uuids[j])) {
                ++errors;
                System.out.println("UUID " + i + " equals UUID " + j);
            }
        }
    }
    assertEquals(errors + " duplicate UUIDS", 0, errors);
    final int variant = uuid.variant();
    assertEquals("Incorrect variant. Expected 2 got " + variant, 2, variant);
    final int version = uuid.version();
    assertEquals("Incorrect version. Expected 1 got " + version, 1, version);
    final long node = uuid.node();
    assertTrue("Invalid node", node != 0);
}

@Test
public void testThreads() throws Exception {
    final Thread[] threads = new Thread[THREADS];
    final UUID[] uuids = new UUID[COUNT * THREADS];
    final long[] elapsed = new long[THREADS];
    for (int i = 0; i < THREADS; ++i) {
        threads[i] = new Worker(uuids, elapsed, i, COUNT);
    }
    for (int i = 0; i < THREADS; ++i) {
        threads[i].start();
    }
    long elapsedTime = 0;
    for (int i = 0; i < THREADS; ++i) {
        threads[i].join();
        elapsedTime += elapsed[i];
    }
    System.out.println("Elapsed for " + COUNT * THREADS + " UUIDS = " + elapsedTime + " Average = " + elapsedTime / (COUNT * THREADS) + " ns");
    int errors = 0;
    for (int i = 0; i < COUNT * THREADS; ++i) {
        for (int j = i + 1; j < COUNT * THREADS; ++j) {
            if (uuids[i].equals(uuids[j])) {
                ++errors;
                System.out.println("UUID " + i + " equals UUID " + j);
            }
        }
    }
    assertEquals(errors + " duplicate UUIDS", 0, errors);
}

@Test
public void testWatchManager() throws Exception {
    Assume.assumeFalse(IS_WINDOWS);
    ConfigurationScheduler scheduler = new ConfigurationScheduler();
    scheduler.incrementScheduledItems();
    WatchManager watchManager = new WatchManager(scheduler);
    watchManager.setIntervalSeconds(1);
    scheduler.start();
    watchManager.start();
    try {
        File sourceFile = new File(originalFile);
        FileOutputStream targetStream = new FileOutputStream(testFile);
        File updateFile = new File(newFile);
        Path source = Paths.get(sourceFile.toURI());
        Files.copy(source, targetStream);
        File targetFile = new File(testFile);
        BlockingQueue<File> queue = new LinkedBlockingQueue<>();
        watchManager.watchFile(targetFile, new TestWatcher(queue));
        Thread.sleep(1000);
        source = Paths.get(updateFile.toURI());
        Files.copy(source, Paths.get(targetFile.toURI()), StandardCopyOption.REPLACE_EXISTING);
        Thread.sleep(1000);
        File f = queue.poll(1, TimeUnit.SECONDS);
        assertNotNull("File change not detected", f);
    } finally {
        watchManager.stop();
        scheduler.stop();
    }
}

